import * as THREE from './.three-check.mjs';
function rectangularHole(cx,cz,w,d){const p=new THREE.Path();p.moveTo(cx-w/2,cz-d/2);p.lineTo(cx-w/2,cz+d/2);p.lineTo(cx+w/2,cz+d/2);p.lineTo(cx+w/2,cz-d/2);p.closePath();return p}
function circularHole(cx,cz,r){const p=new THREE.Path();p.absarc(cx,cz,r,0,Math.PI*2,true);return p}
function shell(){const h=30,c=3,s=new THREE.Shape();s.moveTo(-h+c,-h);s.lineTo(h-c,-h);s.lineTo(h,-h+c);s.lineTo(h,h-c);s.lineTo(h-c,h);s.lineTo(-h+c,h);s.lineTo(-h,h-c);s.lineTo(-h,-h+c);s.closePath();return s}
function extrude(s,t){let g=new THREE.ExtrudeGeometry(s,{depth:t,steps:1,bevelEnabled:false,curveSegments:48});g.translate(0,0,-t/2);g.rotateX(Math.PI/2);g.computeBoundingBox();return g}
let top=shell();top.holes.push(rectangularHole(-24.5,-24.5,4,4),rectangularHole(-5,22,6,14));
let bottom=shell();bottom.holes.push(circularHole(0,0,7),rectangularHole(24.5,-24.5,3,3),rectangularHole(-5,22,6,14));
let shutter=new THREE.Shape();shutter.moveTo(-11,-8);shutter.lineTo(11,-8);shutter.lineTo(11,8);shutter.lineTo(-11,8);shutter.closePath();shutter.holes.push(rectangularHole(-5,0,6,14));
