let cs=new THREE.Shape();cs.moveTo(-hg,oz);cs.absarc(0,0,R,ola,ora,false);cs.lineTo(hg,iz);cs.absarc(0,0,r,ira,ila,true);cs.lineTo(-hg,oz);cs.closePath();
for (const [n,s,t] of [['top',top,2],['bottom',bottom,2],['shutter',shutter,1],['liner',cs,.18]]) {let g=extrude(s,t); console.log(n,'vertices',g.attributes.position.count,'bounds',g.boundingBox.min.toArray(),g.boundingBox.max.toArray(), 'groups',g.groups.length)}
